# For each name box, trace upward from the top of the box

def get_connector_above(ln, center_col, max_lines=50):
    """Find the first connector (|, +, etc.) above the center of the box."""
    # The box is on ln, between pipes at left and right.
    # Above the box, there should be a connector at or near center_col

    # First, find the top of the box (the line with +---+ or the first non-text line above)
    box_top_line = ln
    for up_ln in range(ln - 1, max(0, ln - 5), -1):
        line = lines[up_ln]
        # Check if there's a horizontal bar (---) or connector at this column
        if center_col < len(line):
            ch = line[center_col]
            if ch in '|+':
                box_top_line = up_ln
                break
            # Check if there's a horizontal bar nearby
            for offset in range(-5, 6):
                c = center_col + offset
                if c >= 0 and c < len(line) and line[c] in '+':
                    box_top_line = up_ln
                    center_col = c
                    break

    # Now trace upward from box_top_line
    curr_line = box_top_line
    curr_col = center_col

    # Follow the tree upward
    for _ in range(100):
        if curr_line < 0:
            break

        ch = lines[curr_line][curr_col] if curr_col < len(lines[curr_line]) else ' '

        if ch == '|':
            curr_line -= 1
        elif ch == '+':
            # Try going up
            found_up = False
            for ln in range(curr_line - 1, max(0, curr_line - 5), -1):
                if curr_col < len(lines[ln]) and lines[ln][curr_col] in '|+':
                    curr_line = ln
                    found_up = True
                    break

            if not found_up:
                # Follow horizontal bar
                line = lines[curr_line]
                # Left
                for col in range(curr_col - 1, max(0, curr_col - 40), -1):
                    if col < len(line) and line[col] == '+':
                        # Check above
                        if curr_line > 0 and col < len(lines[curr_line - 1]) and lines[curr_line - 1][col] in '|+':
                            curr_col = col
                            curr_line -= 1
                            found_up = True
                            break
                    elif col < len(line) and line[col] in '|':
                        break

                if not found_up:
                    # Right
                    for col in range(curr_col + 1, min(len(line), curr_col + 40)):
                        if col < len(line) and line[col] == '+':
                            if curr_line > 0 and col < len(lines[curr_line - 1]) and lines[curr_line - 1][col] in '|+':
                                curr_col = col
                                curr_line -= 1
                                found_up = True
                                break
                        elif col < len(line) and line[col] in '|':
                            break

                if not found_up:
                    curr_line -= 1
        elif ch in '-~':
            # Horizontal bar - find where it connects up
            line = lines[curr_line]
            found_up = False
            for col in range(curr_col - 1, max(0, curr_col - 40), -1):
                if col < len(line) and line[col] == '+':
                    if curr_line > 0 and col < len(lines[curr_line - 1]) and lines[curr_line - 1][col] in '|+':
                        curr_col = col
                        curr_line -= 1
                        found_up = True
                        break
                elif col < len(line) and line[col] in '|':
                    break

            if not found_up:
                for col in range(curr_col + 1, min(len(line), curr_col + 40)):
                    if col < len(line) and line[col] == '+':
                        if curr_line > 0 and col < len(lines[curr_line - 1]) and lines[curr_line - 1][col] in '|+':
                            curr_col = col
                            curr_line -= 1
                            found_up = True
                            break
                    elif col < len(line) and line[col] in '|':
                        break

            if not found_up:
                # Check directly above
                if curr_line > 0 and curr_col < len(lines[curr_line - 1]) and lines[curr_line - 1][curr_col] in '|+':
                    curr_line -= 1
                else:
                    curr_line -= 1
        else:
            break

    return curr_line, curr_col

def find_name_at(ln, col):
    """Find a name box near the given position."""
    # Check lines around ln, columns around col
    for line_offset in range(5, -5, -1):
        check_ln = ln + line_offset
        if check_ln < 0 or check_ln >= len(lines):
            continue

        line = lines[check_ln]
        for col_offset in range(-20, 21):
            check_col = col + col_offset
            if check_col < 0 or check_col >= len(line):
                continue

            if line[check_col] in '|│':
                # Found a pipe - find the matching close pipe
                end_pipe = check_col + 1
                while end_pipe < len(line) and line[end_pipe] not in '|│':
                    end_pipe += 1
                if end_pipe < len(line):
                    content = line[check_col+1:end_pipe].strip()
                    if content and len(content) < 30 and not all(c in '-+=~/\\|' for c in content):
                        center = (check_col + end_pipe) // 2
                        key = (check_ln, center)
                        if key in name_boxes:
                            return name_boxes[key]

                        # Check if it's a two-line box
                        if check_ln + 1 < len(lines):
                            next_line = lines[check_ln + 1]
                            if check_col < len(next_line) and end_pipe < len(next_line) and next_line[check_col] in '|│' and next_line[end_pipe] in '|│':
                                last_name = next_line[check_col+1:end_pipe].strip()
                                if last_name:
                                    full = f"{content} {last_name}"
                                    # Check all name boxes
                                    for (nl, nc), nm in name_boxes.items():
                                        if nm == full:
                                            return full
    return None

# Build parent-child relationships
print("\nBuilding parent-child relationships...")
parent_of = {}  # child_name -> parent_name
children_of = {}  # parent_name -> [child_names]

for (ln, center), name in name_boxes.items():
    if name in parent_of:
        continue

    # Find the connector above
    conn_ln, conn_col = get_connector_above(ln, center)

    if conn_ln < 0 or conn_ln >= ln:
        continue

    # Find the name at that position
    parent = find_name_at(conn_ln, conn_col)
    if parent and parent != name:
        parent_of[name] = parent
        if parent not in children_of:
            children_of[parent] = []
        children_of[parent].append(name)

print(f"\nParent-child relationships found: {len(parent_of)}")
for child, parent in sorted(parent_of.items(), key=lambda x: x[1]):
    print(f"  {parent:30s} -> {child:30s}")

# Now trace from Dawid Majtyka upward
print("\nTracing ancestors of Dawid Majtyka:")
if 'Dawid Majtyka' in parent_of:
    current = 'Dawid Majtyka'
    gen = 0
    while current in parent_of:
        print(f"  Gen {gen}: {current}")
        current = parent_of[current]
        gen += 1
        if gen > 20:
            break
    print(f"  Gen {gen}: {current}")
else:
    print("  Dawid Majtyka not found in parent_of")
    # Check all boxes that contain Dawid
    for (ln, center), name in name_boxes.items():
        if 'Dawid' in name:
            print(f"  Found: '{name}' at L{ln+1}, center {center}")
